describe('Profile Picture Upload and Preview', () => {
  beforeEach(() => {
    cy.visit('/profile');
  });

  it('should successfully upload a profile picture and display preview', () => {
    // Intercept the upload API endpoint
    cy.intercept('POST', '/api/profile/picture/upload').as('uploadPicture');

    // Click the upload button
    cy.get('[data-testid="upload-profile-picture-btn"]').click();

    // Verify file input is visible
    cy.get('[data-testid="file-input"]').should('be.visible');

    // Upload a valid image file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/profile-picture.jpg', {
      force: true
    });

    // Verify file name appears in input
    cy.get('[data-testid="file-name-display"]').should('contain', 'profile-picture.jpg');

    // Click the upload button again to trigger upload
    cy.get('[data-testid="upload-profile-picture-btn"]').click();

    // Wait for the upload API call
    cy.wait('@uploadPicture');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Profile picture uploaded successfully');

    // Verify preview image is displayed
    cy.get('[data-testid="profile-picture-preview"]').should('be.visible');
    cy.get('[data-testid="profile-picture-preview img"]').should('have.attr', 'src');

    // Verify preview image has correct dimensions
    cy.get('[data-testid="profile-picture-preview img"]').should('have.css', 'width', '100px');
    cy.get('[data-testid="profile-picture-preview img"]').should('have.css', 'height', '100px');

    // Verify preview image has correct aspect ratio (e.g., 1/1)
    cy.get('[data-testid="profile-picture-preview img"]').should('have.css', 'aspect-ratio', '1 / 1');
  });

  it('should handle invalid file types and display error message', () => {
    // Intercept the upload API endpoint
    cy.intercept('POST', '/api/profile/picture/upload', {
      statusCode: 400,
      body: { error: 'Invalid file type. Only JPG and PNG are allowed.' }
    }).as('uploadPictureError');

    // Click the upload button
    cy.get('[data-testid="upload-profile-picture-btn"]').click();

    // Attempt to upload an invalid file (e.g., PDF)
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document.pdf', {
      force: true
    });

    // Click the upload button
    cy.get('[data-testid="upload-profile-picture-btn"]').click();

    // Wait for the error API call
    cy.wait('@uploadPictureError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid file type');

    // Verify preview is NOT displayed
    cy.get('[data-testid="profile-picture-preview"]').should('not.exist');

    // Verify file input is still visible and ready for retry
    cy.get('[data-testid="file-input"]').should('be.visible');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
